package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="material_requests")
public class MaterialRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="requested_by") private Long requestedBy; @Column(name="material_name") private String materialName; private int quantity; @Column(length=3000) private String justification; @Enumerated(EnumType.STRING) private MaterialRequestStatus status = MaterialRequestStatus.PENDING; @Column(name="reviewed_by") private Long reviewedBy; @Column(name="reviewed_at") private LocalDateTime reviewedAt; @Column(name="review_reason", length=3000) private String reviewReason; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getRequestedBy(){return requestedBy;} public void setRequestedBy(Long requestedBy){this.requestedBy=requestedBy;} public String getMaterialName(){return materialName;} public void setMaterialName(String materialName){this.materialName=materialName;} public int getQuantity(){return quantity;} public void setQuantity(int quantity){this.quantity=quantity;} public String getJustification(){return justification;} public void setJustification(String justification){this.justification=justification;} public MaterialRequestStatus getStatus(){return status;} public void setStatus(MaterialRequestStatus status){this.status=status;} public Long getReviewedBy(){return reviewedBy;} public void setReviewedBy(Long reviewedBy){this.reviewedBy=reviewedBy;} public LocalDateTime getReviewedAt(){return reviewedAt;} public void setReviewedAt(LocalDateTime reviewedAt){this.reviewedAt=reviewedAt;} public String getReviewReason(){return reviewReason;} public void setReviewReason(String reviewReason){this.reviewReason=reviewReason;} }
